    let lightcraft_raw::RawData::U16(d) = &r.data else { panic!("float data") };
    let mut out = Vec::with_capacity(8 + d.len() * 2);
    out.extend_from_slice(&(r.width as u32).to_le_bytes());
    out.extend_from_slice(&(r.height as u32).to_le_bytes());
    for v in d {
